file.content:
        "event_sequence": message["event_sequence"],
        "event_type": message["event_type"],
        "idempotency_key": message["idempotency_key"],
        "payload": message["payload"],
        "status": self._effective_queue_status(message, now),
    }

def queues(self, execution_id: str, tenant: str = DEFAULT_TENANT) -> dict[str, Any]:
    """Queue state and delivery history for one execution, in declaration order."""
    with self._operation():
        with self.store.transaction():
            self.get_execution(execution_id, tenant)
            now = time.time()
            rows = self.store.connection.execute(
                "SELECT name, document FROM queues WHERE tenant = ? AND execution_id = ? ORDER BY position",
                (tenant, execution_id),
            ).fetchall()
            result = []
            for row in rows:
                subscription = self.store.decode(row["document"])
                messages = [
                    self._render_queue_message(
                        message_row["sequence"], self.store.decode(message_row["document"]), now
                    )
                    for message_row in self._queue_message_rows(execution_id, row["name"], tenant)
                ]
                result.append(
                    {
                        "messages": messages,
                        "queue": row["name"],
                        "visibility_seconds": subscription["visibility_seconds"],
                    }
                )
            return {"queues": result}

def pull_queue(
    self, execution_id: str, name: str, raw: Any, key: str | None, tenant: str = DEFAULT_TENANT
) -> dict[str, Any]:
    self._empty_body(raw, "pull")

    def apply() -> dict[str, Any]:
        self.get_execution(execution_id, tenant)
        queue_row = self._queue_row(execution_id, name, tenant)
        if queue_row is None:
            raise NotFoundError(f"queue {name} was not found for execution {execution_id}")
        subscription = self.store.decode(queue_row["document"])
        visibility = subscription["visibility_seconds"]
        now = time.time()
        delivered = []
        for message_row in self._queue_message_rows(execution_id, name, tenant):
            message = self.store.decode(message_row["document"])
            if self._effective_queue_status(message, now) != "pending":
                continue
            # The message leaves the pending set until the visibility
            # deadline; unacknowledged by then, it becomes pending again.
            message["status"] = "delivered"
            message["invisible_until"] = now + visibility
            message["delivery_count"] += 1
            message["deliveries"].append(
                {"delivered_at": self.store.now(), "delivery": message["delivery_count"]}
            )
            self.store.connection.execute(
                "UPDATE queue_messages SET document = ? "
                "WHERE tenant = ? AND execution_id = ? AND queue = ? AND sequence = ?",
                (self.store.encode(message), tenant, execution_id, name, message_row["sequence"]),
            )
            # Every delivery to the caller is metered as a delivery
            # attempt, atomically with the pull that made it.
            self._record_usage(tenant, USAGE_TYPE_DELIVERY_ATTEMPTED)
            delivered.append(self._render_queue_message(message_row["sequence"], message, now))
        # An empty queue (or one with nothing currently deliverable) is a
        # definite empty result, not an error.
        return {"messages": delivered}

    with self._operation():
        return self._idempotent(key, f"pull-queue:{execution_id}:{name}", apply, tenant)

def ack_queue(
    self, execution_id: str, name: str, raw: Any, key: str | None, tenant: str = DEFAULT_TENANT
) -> dict[str, Any]:
    if not isinstance(raw, dict) or set(raw) != {"idempotency_key"}:
        raise ValidationError("ack body must contain exactly an idempotency_key string")
    idempotency_key = raw["idempotency_key"]
    if not isinstance(idempotency_key, str) or not idempotency_key:
        raise ValidationError("ack idempotency_key must be a non-empty string")

    def apply() -> dict[str, Any]:
        self.get_execution(execution_id, tenant)
        if self._queue_row(execution_id, name, tenant) is None:
            raise NotFoundError(f"queue {name} was not found for execution {execution_id}")
        for message_row in self._queue_message_rows(execution_id, name, tenant):
            message = self.store.decode(message_row["document"])
            if message["idempotency_key"] != idempotency_key:
                continue
            if message["status"] == "acknowledged":
                # A repeated acknowledgement names a message that already
                # left the queue: it is missing, like an unknown key.
                raise NotFoundError(f"queue message {idempotency_key} was not found")
            message["status"] = "acknowledged"
            message["invisible_until"] = None
            self.store.connection.execute(
                "UPDATE queue_messages SET document = ? "
                "WHERE tenant = ? AND execution_id = ? AND queue = ? AND sequence = ?",
                (self.store.encode(message), tenant, execution_id, name, message_row["sequence"]),
            )
            return {"acknowledged": True}
        raise NotFoundError(f"queue message {idempotency_key} was not found")

    with self._operation():
        return self._idempotent(key, f"ack-queue:{execution_id}:{name}", apply, tenant)

# --- quotas ---------------------------------------------------------

@staticmethod
def _parse_quota_growth(raw: Any, limits: dict[str, int]) -> dict[str, dict[str, int]]:
    """Validate the optional growth policy of a quota declaration.

    The policy names only the resources it covers; a resource it omits is
    never auto-raised. Each named resource must declare exactly a positive
    integer ``step`` and a positive integer ``cap`` no lower than the
    resource's declared limit.
    """
    if not isinstance(raw, dict):
        raise ValidationError("quota growth must be an object")
    if not raw or set(raw) - set(QUOTA_RESOURCES):
        raise ValidationError("quota growth must name only workflows and executions")
    policy: dict[str, dict[str, int]] = {}
    for kind in QUOTA_RESOURCES:
        if kind not in raw:
            continue
        entry = raw[kind]
        if not isinstance(entry, dict) or set(entry) != {"step", "cap"}:
            raise ValidationError(f"quota growth {kind} must contain exactly step and cap")
        values: dict[str, int] = {}
        for field in ("step", "cap"):
            value = entry[field]
            if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
                raise ValidationError(f"quota growth {kind} {field} must be a positive integer")
            values[field] = value
        if values["cap"] < limits[kind]:
            raise ValidationError(f"quota growth {kind} cap must not be below the declared limit")
        policy[kind] = values
    return policy

def declare_quota(self, raw: Any, key: str | None, tenant: str) -> dict[str, Any]:
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    if not isinstance(raw, dict) or not {"workflows", "executions"} <= set(raw) <= {
        "workflows",
        "executions",
        "growth",
    }:
        raise ValidationError("quota must contain exactly workflows and executions, and optionally growth")
    limits = {}
    for field in ("workflows", "executions"):
        value = raw[field]
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValidationError(f"quota {field} must be a positive integer")
        if value <= 0:
            raise ValidationError(f"quota {field} must be a positive integer")
        limits[field] = value
    # The growth policy is optional; a declaration without one is exactly
    # the two-limit request and removes any policy the tenant had, since a
    # repeated declaration replaces limits and policy as a whole.
    policy = self._parse_quota_growth(raw["growth"], limits) if "growth" in raw else {}

    def apply() -> dict[str, Any]:
        self.store.connection.execute(
            "INSERT INTO quotas(tenant, workflows, executions, "
            "workflows_step, workflows_cap, executions_step, executions_cap, updated_at) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?) "
            "ON CONFLICT(tenant) DO UPDATE SET workflows = excluded.workflows, "
            "executions = excluded.executions, workflows_step = excluded.workflows_step, "
            "workflows_cap = excluded.workflows_cap, executions_step = excluded.executions_step, "
            "executions_cap = excluded.executions_cap, updated_at = excluded.updated_at",
            (
                tenant,
                limits["workflows"],
                limits["executions"],
                policy.get("workflows", {}).get("step"),
                policy.get("workflows", {}).get("cap"),
                policy.get("executions", {}).get("step"),
                policy.get("executions", {}).get("cap"),
                self.store.now(),
            ),
        )
        return self._quota_declaration(limits, policy)

    with self._operation():
        return self._idempotent(key, "declare-quota", apply, tenant)

@staticmethod
def _quota_declaration(
    limits: dict[str, int], policy: dict[str, dict[str, int]]
) -> dict[str, Any]:
    """Render a declaration response (and a stored row back) in stable key order."""
    quota: dict[str, Any] = {"workflows": limits["workflows"], "executions": limits["executions"]}
    if policy:
        # The policy names only the resources the declaration covered,
        # workflows before executions, and within each entry step then cap.
        growth = {
            kind: {"step": policy[kind]["step"], "cap": policy[kind]["cap"]}
            for kind in QUOTA_RESOURCES
            if kind in policy
        }
        quota["growth"] = growth
    return {"quota": quota}

@staticmethod
def _row_policy(row: Any) -> dict[str, dict[str, int]]:
    """Collect the growth policy carried by a quotas row, omitting unmanaged resources."""
    policy: dict[str, dict[str, int]] = {}
    for kind in QUOTA_RESOURCES:
        step, cap = row[f"{kind}_step"], row[f"{kind}_cap"]
        if step is not None and cap is not None:
            policy[kind] = {"step": step, "cap": cap}
    return policy

def get_quota(self, tenant: str) -> dict[str, Any]:
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    with self._operation():
        with self.store.transaction():
            row = self.store.connection.execute(
                "SELECT workflows, executions, workflows_step, workflows_cap, "
                "executions_step, executions_cap FROM quotas WHERE tenant = ?",
                (tenant,),
            ).fetchone()
            if row is None:
                return {"quota": None}
            limits = {"workflows": row["workflows"], "executions": row["executions"]}
            return self._quota_declaration(limits, self._row_policy(row))

def quota_status(self, tenant: str) -> dict[str, Any]:
    """Report each limited resource's declared limit, current holding, and remaining room.

    Read-only: it writes no metering record and changes no declared quota,
    usage, bill, schedule, approval, or replay conclusion. The holding is
    the same real count the quota decision uses (a row count for the
    tenant); the remaining room is limit minus holding, reported truthfully
    as a negative number when a limit was lowered below the current holding
    instead of being clamped to zero. Resources appear workflows first and
    executions second. A tenant that has declared no quota gets the
    definite empty result ``{"status": null}`` — neither resource is listed.
    Another tenant's quota and holdings are never visible.
    """
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    with self._operation():
        with self.store.transaction():
            limits = self._quota_limits(tenant)
            if limits is None:
                return {"status": None}
            status = {}
            for kind in QUOTA_RESOURCES:
                ceiling = limits[kind]
                held = self.store.connection.execute(
                    f"SELECT COUNT(*) AS held FROM {kind} WHERE tenant = ?",
                    (tenant,),
                ).fetchone()["held"]
                status[kind] = {"limit": ceiling, "held": held, "remaining": ceiling - held}
            return {"status": status}

def delete_quota(self, raw: Any, key: str | None, tenant: str) -> dict[str, Any]:
    """Remove the tenant's declared quota as a whole.

    The body must be an empty object; deleting the quota of a tenant that
    never declared one is the same definite empty result as deleting one
    it held. After the delete the tenant holds no declared limits, so both
    quota reads report the never-declared empty results and later writes
    run without quota checks. Existing workflows and executions are not
    deleted or made unusable, recorded usage counts and bill conclusions
    are untouched, and the delete itself writes no metering record. The
    route requires a tenant and an idempotency key: repeating the same
    delete with the same key returns the first result without a second
    effect, while the same key on another operation is the usual 409
    conflict and leaves every declaration in place.
    """
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    self._empty_body(raw, "delete quota")

    def apply() -> dict[str, Any]:
        # Removing a declaration that was never made deletes no row but
        # is still the same definite empty result, never an error.
        self.store.connection.execute(
            "DELETE FROM quotas WHERE tenant = ?",
            (tenant,),
        )
        return {"quota": None}

    with self._operation():
        return self._idempotent(key, "delete-quota", apply, tenant)

def declare_prices(self, raw: Any, key: str | None, tenant: str) -> dict[str, Any]:
    """Declare the tenant's price table, replacing it as a whole.

    The body is a JSON object whose keys name metered types and whose
    values are positive integer-cent prices. A type the table omits keeps
    the built-in default price. A non-object body, a missing or unknown
    field, or a non-positive, non-integer, boolean, or non-finite price is
    a validation error that writes nothing. The route requires a tenant
    and an idempotency key; repeating the same declaration with the same
    key returns the first result without a second replacement, while the
    same key on another operation is the usual 409 conflict.
    """
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    if not isinstance(raw, dict) or not raw:
        raise ValidationError("prices must be a non-empty object of metered types to positive integer prices")
    prices: dict[str, int] = {}
    for usage_type, value in raw.items():
        if usage_type not in USAGE_TYPES:
            raise ValidationError(f"unknown metered type: {usage_type}")
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValidationError(f"price for {usage_type} must be a positive integer")
        if value <= 0:
            raise ValidationError(f"price for {usage_type} must be a positive integer")
        prices[usage_type] = value
    document = self.store.encode(prices)

from __future__ import annotations

import math
from typing import Any
from urllib.parse import urlsplit

from .errors import ValidationError

# The only business events a subscription may declare interest in. A
# termination is a single event type regardless of its reason.
NOTIFY_EVENT_TYPES = ("node_completed", "execution_completed", "execution_terminated", "approval_decided")

# The largest delivery max_attempts a subscription may declare; the allowed
# range is 1 through this value.
MAX_DELIVERY_ATTEMPTS = 10
# The outbound delivery timeout a subscription gets when it declares none.
DEFAULT_TIMEOUT_SECONDS = 5.0
# The number of delivery attempts a subscription gets when it declares none.
DEFAULT_MAX_ATTEMPTS = 1

# A queue target hides a pulled message for this many seconds unless the
# caller acknowledges it first; the declaration may override it with any
# positive number of seconds.
DEFAULT_VISIBILITY_SECONDS = 30


def _parse_events(raw: Any) -> list[str]:
    if not isinstance(raw, list) or not raw:
        raise ValidationError("subscription events must be a non-empty array")
    if any(not isinstance(event, str) or event not in NOTIFY_EVENT_TYPES for event in raw):
        raise ValidationError("subscription events must only contain known event types")
    if len(set(raw)) != len(raw):
        raise ValidationError("subscription events must not contain duplicates")
    return list(raw)


def parse_subscriptions(raw: Any) -> list[dict[str, Any]]:
    """Validate a declared subscription list and return it normalized.

    Every entry is either a webhook target (a url with an optional delivery
    timeout and attempt count) or a queue target (a queue name with an
    optional visibility timeout); exactly one of the two shapes must be
    declared. Defaults are filled in so delivery never re-checks for missing
    fields.
    """
    if not isinstance(raw, list):
        raise ValidationError("subscriptions must be an array")
    subscriptions: list[dict[str, Any]] = []
    for item in raw:
        if not isinstance(item, dict):
            raise ValidationError("each subscription must be an object")
        has_url = "url" in item
        has_queue = "queue" in item
        if has_url == has_queue:
            raise ValidationError("each subscription must declare exactly one of url or queue")
        if "events" not in item:
            raise ValidationError("each subscription must contain url and events, or queue and events")
        events = _parse_events(item["events"])
        if has_url:
            if not set(item) <= {"url", "events", "timeout_seconds", "max_attempts"}:
                raise ValidationError(
                    "each subscription must contain url and events, and optionally timeout_seconds and max_attempts"
                )
            url = item["url"]
            if not isinstance(url, str) or not url:
                raise ValidationError("subscription url must be a non-empty string")
            parts = urlsplit(url)
            if parts.scheme not in ("http", "https") or not parts.netloc:
                raise ValidationError("subscription url must be an http or https address")
            timeout = item.get("timeout_seconds", DEFAULT_TIMEOUT_SECONDS)
            if isinstance(timeout, bool) or not isinstance(timeout, (int, float)):
                raise ValidationError("subscription timeout_seconds must be a positive number of seconds")
            if not math.isfinite(timeout) or timeout <= 0:
                raise ValidationError("subscription timeout_seconds must be a positive number of seconds")
            max_attempts = item.get("max_attempts", DEFAULT_MAX_ATTEMPTS)
            if isinstance(max_attempts, bool) or not isinstance(max_attempts, int):
                raise ValidationError(f"subscription max_attempts must be an integer between 1 and {MAX_DELIVERY_ATTEMPTS}")
            if not 1 <= max_attempts <= MAX_DELIVERY_ATTEMPTS:
                raise ValidationError(f"subscription max_attempts must be an integer between 1 and {MAX_DELIVERY_ATTEMPTS}")
            subscriptions.append(
                {"url": url, "events": events, "timeout_seconds": timeout, "max_attempts": max_attempts}
            )
        else:
            if not set(item) <= {"queue", "events", "visibility_seconds"}:
                raise ValidationError(
                    "each queue subscription must contain queue and events, and optionally visibility_seconds"
                )
            name = item["queue"]
            if not isinstance(name, str) or not name:
                raise ValidationError("subscription queue must be a non-empty string")
            visibility = item.get("visibility_seconds", DEFAULT_VISIBILITY_SECONDS)
            if isinstance(visibility, bool) or not isinstance(visibility, (int, float)):
                raise ValidationError("subscription visibility_seconds must be a positive number of seconds")
            if not math.isfinite(visibility) or visibility <= 0:
                raise ValidationError("subscription visibility_seconds must be a positive number of seconds")
            subscriptions.append({"queue": name, "events": events, "visibility_seconds": visibility})
    return subscriptions

def _empty_body(raw: Any, operation: str) -> None:
    if not isinstance(raw, dict) or raw:
        raise ValidationError(f"{operation} body must be an empty object")

def pause_schedule(
    self, workflow_id: str, raw: Any, key: str | None, tenant: str = DEFAULT_TENANT
) -> dict[str, Any]:
    self._empty_body(raw, "pause schedule")

    def apply() -> dict[str, Any]:
        self._assert_workflow_exists(workflow_id, tenant)
        if self._schedule_row(workflow_id, tenant) is None:
            raise NotFoundError(f"workflow {workflow_id} has no schedule")
        self.store.connection.execute(
            "UPDATE schedules SET paused = 1 WHERE tenant = ? AND workflow_id = ?",
            (tenant, workflow_id),
        )
        return self._schedule_status(self._schedule_row(workflow_id, tenant))

    with self._operation():
        return self._idempotent(key, f"pause-schedule:{workflow_id}", apply, tenant)

def resume_schedule(
    self, workflow_id: str, raw: Any, key: str | None, tenant: str = DEFAULT_TENANT
) -> dict[str, Any]:
    self._empty_body(raw, "resume schedule")

    def apply() -> dict[str, Any]:
        self._assert_workflow_exists(workflow_id, tenant)
        if self._schedule_row(workflow_id, tenant) is None:
            raise NotFoundError(f"workflow {workflow_id} has no schedule")
        self.store.connection.execute(
            "UPDATE schedules SET paused = 0 WHERE tenant = ? AND workflow_id = ?",
            (tenant, workflow_id),
        )
        # Periods that came due while paused are settled immediately
        # according to the missed policy.
        self._process_schedules(workflow_id, tenant)
        return self._schedule_status(self._schedule_row(workflow_id, tenant))

    with self._operation():
        return self._idempotent(key, f"resume-schedule:{workflow_id}", apply, tenant)

def update_schedule(
    self, workflow_id: str, raw: Any, key: str | None, tenant: str = DEFAULT_TENANT
) -> dict[str, Any]:
    # The whole plan is validated before anything is written, so an
    # invalid declaration never partially replaces the stored one.
    schedule = parse_schedule(raw)

    def apply() -> dict[str, Any]:
        self._assert_workflow_exists(workflow_id, tenant)
        self._insert_schedule(workflow_id, schedule, tenant)
        return self._schedule_status(self._schedule_row(workflow_id, tenant))

    with self._operation():
        return self._idempotent(key, f"update-schedule:{workflow_id}", apply, tenant)

def _set_schedule_cursor(self, tenant: str, workflow_id: str, cursor: str) -> None:
    self.store.connection.execute(
        "UPDATE schedules SET cursor = ? WHERE tenant = ? AND workflow_id = ?",
        (cursor, tenant, workflow_id),
    )

def _process_schedules(self, workflow_id: str | None = None, tenant: str | None = None) -> None:
    """Settle every due schedule period once; caller holds a transaction."""
    now = time.time()
    if workflow_id is None:
        rows = self.store.connection.execute(
            "SELECT tenant, workflow_id, document, paused, anchor_at, cursor FROM schedules"
        ).fetchall()
    else:
        rows = self.store.connection.execute(
            "SELECT tenant, workflow_id, document, paused, anchor_at, cursor FROM schedules "
            "WHERE tenant = ? AND workflow_id = ?",
            (tenant or DEFAULT_TENANT, workflow_id),
        ).fetchall()
    for row in rows:
        self._process_schedule(row, now)

